        let input = vec![
            Complex { re: 7, im: 0 },
            Complex { re: -1, im: 0 },
        ];
        // Even though we go into the "all_close" branch, zeroing the imaginary parts leaves them unchanged
        let result = real_if_close(input.clone(), 10);
        assert_eq!(result, input);
